'use strict';

// MODULES //

var basename = require( 'path' ).basename;
var join = require( 'path' ).join;
var db = require( '@stdlib/math/special/scripts/function_database.json' );
var cartesianProduct = require( '@stdlib/array/cartesian-product' );
var dtypes = require( '@stdlib/ndarray/dtypes' );
var DTYPE_HIERARCHY = require( '@stdlib/math/special/scripts/dtype_hierarchy.js' );
var NDARRAY_KERNELS = require( '@stdlib/ndarray/base/unary/data/function_list.json' );
var mapToScalarKernel = require( './map_to_scalar_kernel.js' );
var getDtypes = require( './get_dtypes.js' );
var config = require( './config.js' );


// VARIABLES //

var DTYPES = {};
var basePkg = basename( join( __dirname, '..' ) );


// MAIN //

/**
* Main execution sequence.
*
* ## Note
*
* -   The function generates an array of matches, where each match is an array of the following format:
*
* ```text
*             ----------------------------------------------------------------------------------------------------------------------------------------
*  Array:    | input_dtype | output_dtype | package | needs_to_promote | promoted_input_dtype | promoted_output_dtype | c_function_name | loop_kernel |
*             ----------------------------------------------------------------------------------------------------------------------------------------
*                   |              |           |            |                     |                      |                      |              |
*                   |              |           |            |                     |                      |                      |              |
*                   V              V           |            V                     V                      V                      |              V
*  Example:     'float32'       'float64'      |           true               'float64'              'float64'                  |       'stdlib_ndarray_f_d_as_d_d'
*                                              V                                                                                V
*                               '@stdlib/math/base/special/sqrt'                                                         'stdlib_base_sqrt'
* ```
*
* @private
* @returns {Array} array of mappings
*/
function main() {
	var outputPrecision;
	var needsPromotion;
	var inputPrecision;
	var outputDtype;
	var inputDtype;
	var filtered = [];
	var mappings;
	var kernels = [];
	var iopairs;
	var mapping;
	var iodt = [];
	var seen = {};
	var odt;
	var idt;
	var out;
	var obj;
	var dt;
	var k;
	var i;

	// Resolve list of input dtypes:
	idt = dtypes( config.input_dtypes );
	filtered = [];
	for ( i = 0; i < idt.length; i++ ) {
		if ( config.excluded_dtypes.indexOf( idt[ i ] ) === -1 ) { // Exclude irrelevant dtypes
			filtered.push( idt[ i ] );
		}
	}
	idt = filtered;

	/*
	For example, we'll have:
	idt = [
		'float32',
		'float64',
		'int16',
		'int32',
		'int8',
		'uint16',
		'uint32',
		'uint8',
		'generic'
	]
	*/

	// Resolve the list of output dtypes:
	odt = dtypes( config.output_dtypes );
	filtered = [];
	for ( i = 0; i < odt.length; i++ ) {
		if ( config.excluded_dtypes.indexOf( odt[ i ] ) === -1 ) { // Exclude irrelevant dtypes
			filtered.push( odt[ i ] );
		}
	}
	odt = filtered;

	/*
	For example, we'll have:
	odt = [
		'float32',
		'float64'
	]
	*/

	// Computing the Cartesian product of input and output dtypes:
	iopairs = cartesianProduct( idt, odt );

	/*
	For example, we'll have:
	iopairs = [
		[ 'float32', 'float32' ],
		[ 'float32', 'float64' ],
		[ 'float64', 'float32' ],
		[ 'float64', 'float64' ],
		...
	]
	*/

	// Filter based on dtype hierarchy:
	for ( i = 0; i < iopairs.length; i++ ) {
		inputDtype = iopairs[ i ][ 0 ];
		outputDtype = iopairs[ i ][ 1 ];
		inputPrecision = DTYPE_HIERARCHY[ inputDtype ] || 0;
		outputPrecision = DTYPE_HIERARCHY[ outputDtype ] || 0;

		// Only allow upcasts (higher or equal precision) or same dtype or generic source:
		if ( inputDtype === outputDtype || inputDtype === 'generic' || outputPrecision >= inputPrecision ) {
			filtered.push( iopairs[ i ] );
		}
	}
	iopairs = filtered;

	/*
	For example, we'll have:
	iopairs = [
		[ 'float32', 'float32' ],
		[ 'float32', 'float64' ],
		[ 'float64', 'float64' ],
		...
	]
	*/

	// Get the list of dtypes with scalar math kernels:
	obj = db[ basePkg ];

	/*
	For example, we'll have:
	obj = {
		"input_dtypes": "real_and_generic",
		"output_dtypes": "real_floating_point",
		"output_policy": "real_floating_point",
		"scalar_kernels": {
			"float32": "@stdlib/math/base/special/sqrtf",
			"float64": "@stdlib/math/base/special/sqrt",
			"generic": "@stdlib/math/base/special/sqrt"
		}
	}
	*/

	/*
	Available scalar kernel dtypes:
	objectKeys( obj.scalar_kernels ) = [
		'float32',
		'float64'
	]
	*/

	// Build a list of scalar kernels based on output dtype:
	for ( i = 0; iopairs && i < iopairs.length; i++ ) {
		out = iopairs[ i ][ 1 ];

		// For generic input, always use highest precision kernel:
		if ( iopairs[ i ][ 0 ] === 'generic' ) {
			k = obj.scalar_kernels.float64 || obj.scalar_kernels.generic;
		} else {
			k = obj.scalar_kernels[ out ] || obj.scalar_kernels.generic;
		}

		if ( k && !seen[ k ] ) {
			seen[ k ] = true;
			kernels.push( k );
		}
	}

	// Resolve the input-output dtypes for each unique scalar kernel:
	iodt = [];
	for ( i = 0; i < kernels.length; i++ ) {
		if ( DTYPES[ kernels[ i ] ] ) {
			iodt.push( DTYPES[ kernels[ i ] ] );
			continue;
		}
		dt = getDtypes( kernels[ i ] );
		DTYPES[ kernels[ i ] ] = dt;
		iodt.push( dt );
	}

	// Map dtype pairs to appropriate scalar functions based on prioritization rules:
	mappings = [];
	for ( i = 0; i < iopairs.length; i++ ) {
		mapping = mapToScalarKernel( iopairs[ i ], iodt, obj.scalar_kernels );
		if ( mapping && mapping.length === 4 ) {
			// Verify that the ndarray kernel exists in the function list
			if ( NDARRAY_KERNELS.indexOf( mapping[ 2 ] ) !== -1 ) {
				// Check if promotion is needed...
				needsPromotion = mapping[ 3 ][ 0 ] !== iopairs[ i ][ 0 ] ||
					mapping[ 3 ][ 1 ] !== iopairs[ i ][ 1 ];

				// [ input_dtype, output_dtype, package, needs_to_promote, promoted_input_dtype, promoted_output_dtype, c_function_name, loop_kernel ]...
				mappings.push([ iopairs[ i ][ 0 ], iopairs[ i ][ 1 ], mapping[ 0 ], needsPromotion, ( needsPromotion ) ? mapping[ 3 ][ 0 ] : null, ( needsPromotion ) ? mapping[ 3 ][ 1 ] : null, mapping[ 1 ], mapping[ 2 ] ]); // eslint-disable-line max-len
			}
		}
	}

	/*
	For example, we'll have:
	mappings = [
		[ 'int8', 'float32', '@stdlib/math/base/special/sqrtf', true, 'float32', 'float32', 'stdlib_base_sqrtf', 'stdlib_ndarray_s_f_as_f_f' ],
		[ 'float32', 'float32', '@stdlib/math/base/special/sqrtf', false, null, null, 'stdlib_base_sqrtf', 'stdlib_ndarray_f_f' ],
		[ 'float32', 'float64', '@stdlib/math/base/special/sqrt', true, 'float64', 'float64', 'stdlib_base_sqrt', 'stdlib_ndarray_f_d_as_d_d' ],
		[ 'float64', 'float64', '@stdlib/math/base/special/sqrt', false, null, null, 'stdlib_base_sqrt', 'stdlib_ndarray_d_d' ],
		...
	]
	*/

	return mappings;
}


// EXPORTS //

module.exports = main;
